INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('d49ad500-406b-4d12-b849-061cfe8a40e8', 'LOST', 'OPEN', 'Smarrito Pongo, meticcio marrone, zona Trastevere', 'DOG', 'Meticcio', 'Pongo', 'M', 'ADULTO', 'MEDIA', 'Marrone con macchia bianca sul petto', 1, '380260012345678', 1, 1, 1, NULL, NULL, 'Pongo e scappato durante i fuochi d artificio di sabato sera. E molto timido con gli sconosciuti e tende a nascondersi sotto le auto parcheggiate.', 'Non inseguitelo: si spaventa e scappa. Se lo vedete, sedetevi a terra e chiamatelo con voce bassa, oppure avvisatemi subito con la posizione.', 'Piazza Trilussa', 'Roma', 'RM', 41.8896, 12.4695, 1788044219, 1788044219, 1788044219, NULL, 'Giulia Rossi', '333 1234567', 'giulia@example.it', '8b36da85-30c2-4172-8f4b-3b29bb3000ac');
INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('5a09254a-d443-442f-bbc4-748957078ebb', 'FOUND', 'OPEN', 'Trovato gatto tigrato vicino al Parco Sempione', 'CAT', 'Europeo', NULL, 'F', 'GIOVANE', 'PICCOLA', 'Tigrata grigia, punta della coda bianca', 0, NULL, 0, NULL, NULL, NULL, NULL, 'Trovata ieri sera vicino all ingresso del parco. E in buona salute, molto affettuosa e affamata. Per ora la tengo io in casa, al sicuro.', 'Sembra abituata a stare in appartamento. Chi la riconosce mi descriva un segno particolare prima di venire a prenderla.', 'Parco Sempione, ingresso Arco della Pace', 'Milano', 'MI', 45.4756, 9.1725, 1788217019, 1788217019, 1788217019, NULL, 'Marco Bianchi', '347 7654321', 'marco@example.it', '0076b13c-b4d8-471c-b41c-1e4668da1a2b');
INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('de4f6e48-daea-4b8d-8994-3171ff65a26d', 'ADOPTION', 'OPEN', 'Luna cerca casa: dolcissima, sterilizzata e vaccinata', 'DOG', 'Meticcio taglia media', 'Luna', 'F', 'ADULTO', 'MEDIA', 'Nera con petto bianco', 1, NULL, 0, 1, 1, 1, 1, 'Luna ha circa 4 anni, e stata recuperata da una cucciolata di strada e vive in stallo da otto mesi. E equilibrata, cammina bene al guinzaglio e adora i bambini.', 'Cerchiamo una famiglia con un po di spazio e tempo per le passeggiate. Affido con preaffido e controlli post adozione. Consegna in tutta la Campania.', 'Zona Vomero', 'Napoli', 'NA', 40.8449, 14.2298, 1785711419, 1787785019, 1787785019, NULL, 'Sara Conti', '340 9988776', 'sara@example.it', '202771c0-c71b-4c8b-9bf8-d5cd65a6fb78');
INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('c01c6e1f-baa5-4273-a778-c81f008fa833', 'LOST', 'OPEN', 'Smarrito pappagallino verde in zona San Giovanni', 'BIRD', NULL, 'Kiwi', 'M', 'GIOVANE', 'PICCOLA', 'Verde con testa gialla', 0, NULL, 0, NULL, NULL, NULL, NULL, 'Kiwi e volato via da una finestra aperta martedi mattina. Non e abituato a stare fuori e risponde al suo nome fischiettando.', 'Si posa spesso su balconi e tende da sole. Se lo vedete, provate a mettere una ciotola d acqua e avvisatemi.', 'Via Appia Nuova, altezza San Giovanni', 'Roma', 'RM', 41.8848, 12.5119, 1788130619, 1788130619, 1788130619, NULL, 'Giulia Rossi', '333 1234567', 'giulia@example.it', '8b36da85-30c2-4172-8f4b-3b29bb3000ac');
INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('34a01725-5761-458b-a24b-8396c675b257', 'ADOPTION', 'OPEN', 'Due gattini di 3 mesi cercano famiglia (adozione di coppia)', 'CAT', 'Europeo', NULL, 'UNKNOWN', 'CUCCIOLO', 'PICCOLA', 'Uno nero, uno bianco e rosso', 0, NULL, 0, NULL, 1, 1, 1, 'Fratellini trovati in un cortile a luglio. Sono svezzati, usano la lettiera e sono abituati alla presenza di persone. Li diamo solo insieme.', 'Prima vaccinazione fatta, sverminati. Richiesta zanzariera alle finestre.', 'Zona Navigli', 'Milano', 'MI', 45.4498, 9.1755, 1787439419, 1787957819, 1787957819, NULL, 'Marco Bianchi', '347 7654321', 'marco@example.it', '0076b13c-b4d8-471c-b41c-1e4668da1a2b');
INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('549bf558-fb1f-4a75-ba01-9c71b05fec57', 'FOUND', 'OPEN', 'Trovato coniglio nano in un giardino condominiale', 'RABBIT', NULL, NULL, 'UNKNOWN', 'ADULTO', 'PICCOLA', 'Bianco e marrone', 0, NULL, 0, NULL, NULL, NULL, NULL, 'Girava spaventato nel cortile del palazzo. E chiaramente un animale domestico: si lascia prendere in braccio senza problemi.', 'Lo tengo in un box al chiuso. Cerco il proprietario prima di trovargli una casa.', 'Via Toledo', 'Napoli', 'NA', 40.8419, 14.2489, 1787871419, 1787871419, 1787871419, NULL, 'Sara Conti', '340 9988776', 'sara@example.it', '202771c0-c71b-4c8b-9bf8-d5cd65a6fb78');
INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('b8e3c36b-27fb-4382-8e96-71d7153abe23', 'LOST', 'OPEN', 'Smarrita gatta rossa a Monteverde, risponde a Zoe', 'CAT', NULL, 'Zoe', 'F', 'ADULTO', 'MEDIA', 'Rossa, occhi verdi', 1, NULL, 0, 1, NULL, NULL, NULL, 'Zoe e uscita dal terrazzo giovedi notte. Non e abituata alla strada, probabilmente si e nascosta in un garage o in un giardino della zona.', 'Se sentite miagolare in un box o in una cantina, per favore controllate e chiamatemi a qualsiasi ora.', 'Via Fonteiana, Monteverde', 'Roma', 'RM', 41.8798, 12.4526, 1788217019, 1788217019, 1788217019, NULL, 'Giulia Rossi', '333 1234567', 'giulia@example.it', '8b36da85-30c2-4172-8f4b-3b29bb3000ac');
INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('e73f19a4-4d0f-48f9-b80f-9b14286245af', 'LOST', 'OPEN', 'Scappato Pepe, geco leopardino, zona Testaccio', 'GECKO', NULL, 'Pepe', NULL, 'ADULTO', 'PICCOLA', 'Giallo con macchie scure, circa 20 cm con la coda', 0, NULL, 0, NULL, NULL, NULL, NULL, 'Pepe e uscito dal terrario mentre pulivo il vetro. Si muove lentamente e cerca sempre i posti caldi, quindi non dovrebbe essersi allontanato molto.', 'Controllate dietro i termosifoni, sotto i mobili e vicino alle prese: cerca il tepore. Non prendetelo per la coda, si stacca: meglio appoggiargli sopra una scatola e chiamarmi.', 'Via Marmorata, Testaccio', 'Roma', 'RM', 41.8781, 12.4753, 1788130619, 1788130619, 1788130619, NULL, 'Giulia Rossi', '333 1234567', 'giulia@example.it', '8b36da85-30c2-4172-8f4b-3b29bb3000ac');
INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('025f2e21-dd15-4a53-b7cb-4dd542cebeed', 'FOUND', 'OPEN', 'Trovato criceto dorato in un cortile condominiale', 'HAMSTER', NULL, NULL, NULL, 'ADULTO', 'PICCOLA', 'Dorato con la pancia bianca', 0, NULL, 0, NULL, NULL, NULL, NULL, 'Girava tra le foglie vicino ai bidoni, spaventato e infreddolito. Per ora l ho messo in una gabbia con acqua e semi: sta bene, ma e magro.', 'Probabilmente era fuori da qualche giorno. Cerco chi l ha perso prima di trovargli una casa nuova.', 'Via Ostiense, cortile interno', 'Roma', 'RM', 41.8712, 12.4801, 1788217019, 1788217019, 1788217019, NULL, 'Sara Conti', '340 9988776', 'sara@example.it', '202771c0-c71b-4c8b-9bf8-d5cd65a6fb78');
INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('4145d252-b212-49ad-98ed-f844aba49082', 'ADOPTION', 'OPEN', 'Cannella e Zucchero, porcellini d India, cercano casa insieme', 'GUINEA_PIG', NULL, NULL, 'F', 'ADULTO', 'PICCOLA', 'Una fulva, una bianca e nera', 0, NULL, 0, NULL, NULL, 1, 1, 'Due sorelle di un anno e mezzo, socievoli e molto chiacchierone: fischiano appena sentono aprire il frigo. Vanno adottate insieme, si sono sempre fatte compagnia.', 'Servono una gabbia ampia, fieno sempre disponibile e verdura fresca ogni giorno per la vitamina C, che non producono da sole. Consegniamo la gabbia con loro.', 'Zona Citta Studi', 'Milano', 'MI', 45.4781, 9.2278, 1786575419, 1788044219, 1788044219, NULL, 'Marco Bianchi', '347 7654321', 'marco@example.it', '0076b13c-b4d8-471c-b41c-1e4668da1a2b');
INSERT INTO "posts" ("id", "kind", "status", "title", "species", "breed", "pet_name", "sex", "age_range", "size", "color", "has_microchip", "microchip", "has_collar", "neutered", "vaccinated", "good_with_kids", "good_with_pets", "description", "extra_notes", "address", "city", "province", "lat", "lng", "event_date", "created_at", "updated_at", "resolved_at", "contact_name", "contact_phone", "contact_email", "author_id") VALUES ('4b8d2e83-3206-4773-9d34-06bb848ed00f', 'LOST', 'OPEN', 'Smarrito Whisky, beagle, zona Bologna centro', 'DOG', 'Beagle', 'Whisky', 'M', 'ADULTO', 'MEDIA', 'Tricolore classico beagle', 1, NULL, 1, NULL, 1, NULL, NULL, 'Whisky ha seguito una traccia durante una passeggiata e si e allontanato ai Giardini Margherita. E goloso e si avvicina a chi ha del cibo.', 'Collare rosso con medaglietta e numero di telefono inciso.', 'Giardini Margherita', 'Bologna', 'BO', 44.4813, 11.3548, 1787698619, 1787698619, 1787698619, NULL, 'Marco Bianchi', '347 7654321', 'marco@example.it', '0076b13c-b4d8-471c-b41c-1e4668da1a2b');
